//tets generated by coPilot as an example of a suitable test.

import { QuestionJSONStitcher } from '../JSON_providers_and_workers/QuestionJSONStitcher.js';

describe('QuestionJSONStitcher', () => {
  it('removes drag_and_drop and card_match from question extensions', () => {
    const errorReporter = { reportError: jest.fn() };
    const stitcher = new QuestionJSONStitcher(errorReporter);

    const examData = {
      question_groups: [{
        questions: [{
          extensions: ['drag_and_drop', 'manual_marking', 'card_match', 'some_other_extension'],
          custom_part_types: [],
          variables: {},
          ungrouped_variables: []
        }]
      }]
    };

    const question = { extensions: [] };
    stitcher.removeUnwantedExtensions(question, 0, examData);

    const extensions = examData.question_groups[0].questions[0].extensions;
    expect(extensions).not.toContain('drag_and_drop');
    expect(extensions).not.toContain('manual_marking');
    expect(extensions).not.toContain('card_match');
    expect(errorReporter.reportError).not.toHaveBeenCalled();
  });
});